declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('suppliers.manage');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM suppliers WHERE id=:id');$st->execute([':id'=>$id]);$supplier=$st->fetch();if(!$supplier){flash('error','Supplier not found.');redirect('suppliers/index');}$data=[];foreach(['name','contact_person','phone','alternate_phone','email','address','tax_number','notes','status']as$k)$data[$k]=(string)($supplier[$k]??'');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();foreach(array_keys($data)as$k)$data[$k]=trim((string)($_POST[$k]??''));if(mb_strlen($data['name'])<2)$errors['name']='Enter a supplier name.';if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email.';if(!$errors){$up=db()->prepare('UPDATE suppliers SET name=:name,contact_person=:contact,phone=:phone,alternate_phone=:alt,email=:email,address=:address,tax_number=:tax,notes=:notes,status=:status WHERE id=:id');$up->execute([':name'=>$data['name'],':contact'=>$data['contact_person']?:null,':phone'=>$data['phone']?:null,':alt'=>$data['alternate_phone']?:null,':email'=>$data['email']?:null,':address'=>$data['address']?:null,':tax'=>$data['tax_number']?:null,':notes'=>$data['notes']?:null,':status'=>$data['status'],':id'=>$id]);audit_log('supplier_updated','suppliers',$id,'Supplier updated: '.$data['name'].'.');flash('success','Supplier updated.');redirect('suppliers/view?id='.$id);}}
$pageTitle='Edit Supplier';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
